/**
 * Canonical sign: torque is torque ON the named component, not torque
 * generated BY it. Positive T * omega means power enters the component.
 * An engine delivering shaft power has negative power at its output port.
 */
export interface RotationalPortSample {
  readonly componentId: string;
  readonly portId: string;
  readonly simulationTick: number;
  readonly torqueOnComponentNm: number;
  readonly angularVelocityRadPerSecond: number;
}

export interface PowerBalanceOptions {
  /** Irreversible dissipation at the interconnect, always >= 0 W. */
  readonly dissipatedPowerW?: number;
  /** Positive when energy accumulates in the interconnect, in W. */
  readonly storedEnergyRateW?: number;
  readonly absoluteToleranceW?: number;
  readonly relativeTolerance?: number;
}

export interface PowerBalanceResult {
  readonly simulationTick: number;
  readonly powerIntoComponentsW: number;
  readonly residualW: number;
  readonly toleranceW: number;
  readonly balanced: boolean;
}

function finite(value: number, label: string): number {
  if (!Number.isFinite(value)) throw new RangeError(`${label}: must be finite`);
  return value;
}

export function rotationalPowerIntoComponentW(
  torqueOnComponentNm: number,
  angularVelocityRadPerSecond: number,
): number {
  return (
    finite(torqueOnComponentNm, 'torqueOnComponentNm') *
    finite(angularVelocityRadPerSecond, 'angularVelocityRadPerSecond')
  );
}

/**
 * For a link, sum(power INTO each endpoint) + loss + dE/dt = 0.
 * This works with gears, reverse rotation, motoring and losses; it does not
 * assume equal shaft speeds or blindly apply efficiency to reverse loads.
 */
export function checkRotationalPowerBalance(
  samples: readonly RotationalPortSample[],
  options: PowerBalanceOptions = {},
): PowerBalanceResult {
  if (samples.length < 2) {
    throw new RangeError('power balance requires at least two ports');
  }
  const tick = samples[0]!.simulationTick;
  if (!Number.isSafeInteger(tick) || tick < 0) {
    throw new RangeError('simulationTick: invalid tick');
  }
  let powerIntoComponentsW = 0;
  let largestPowerW = 0;
  const endpoints = new Set<string>();
  for (const sample of samples) {
    if (sample.simulationTick !== tick) {
      throw new Error('power balance: samples use different simulation ticks');
    }
    const key = `${sample.componentId}/${sample.portId}`;
    if (endpoints.has(key)) throw new Error('power balance: duplicate port');
    endpoints.add(key);
    const power = rotationalPowerIntoComponentW(
      sample.torqueOnComponentNm,
      sample.angularVelocityRadPerSecond,
    );
    powerIntoComponentsW += power;
    largestPowerW = Math.max(largestPowerW, Math.abs(power));
  }
  const dissipated = finite(options.dissipatedPowerW ?? 0, 'dissipatedPowerW');
  const stored = finite(options.storedEnergyRateW ?? 0, 'storedEnergyRateW');
  const absolute = finite(options.absoluteToleranceW ?? 1e-9, 'absoluteToleranceW');
  const relative = finite(options.relativeTolerance ?? 1e-9, 'relativeTolerance');
  if (dissipated < 0 || absolute < 0 || relative < 0) {
    throw new RangeError('dissipation/tolerances must be nonnegative');
  }
  const residualW = powerIntoComponentsW + dissipated + stored;
  const toleranceW = absolute + relative * largestPowerW;
  return {
    simulationTick: tick,
    powerIntoComponentsW,
    residualW,
    toleranceW,
    balanced: Math.abs(residualW) <= toleranceW,
  };
}
